// Config plugin: sign Android release builds with the Play upload key.
// android/ is generated by `expo prebuild`, so this re-applies the change on every prebuild instead of
// hand-editing build.gradle. The key and passwords never enter the repo; set them in ~/.gradle/gradle.properties:
//
//   HOURLINE_UPLOAD_STORE_FILE=/absolute/path/to/hourline-upload.keystore
//   HOURLINE_UPLOAD_STORE_PASSWORD=...
//   HOURLINE_UPLOAD_KEY_ALIAS=hourline-upload
//   HOURLINE_UPLOAD_KEY_PASSWORD=...
//
// Without them, release builds fall back to the debug key (fine for local testing, rejected by Google Play)
// and Gradle prints a warning.
const { withAppBuildGradle } = require('expo/config-plugins');

const MARKER = '// @hourline-upload-signing';

const RELEASE_SIGNING_CONFIG = `
        ${MARKER}
        release {
            if (findProperty('HOURLINE_UPLOAD_STORE_FILE')) {
                storeFile file(findProperty('HOURLINE_UPLOAD_STORE_FILE'))
                storePassword findProperty('HOURLINE_UPLOAD_STORE_PASSWORD')
                keyAlias findProperty('HOURLINE_UPLOAD_KEY_ALIAS')
                keyPassword findProperty('HOURLINE_UPLOAD_KEY_PASSWORD')
            }
        }`;

const RELEASE_SIGNING_LINE = `signingConfig findProperty('HOURLINE_UPLOAD_STORE_FILE') ? signingConfigs.release : signingConfigs.debug
            if (!findProperty('HOURLINE_UPLOAD_STORE_FILE')) {
                logger.warn('Hourline: release build signed with the DEBUG key (HOURLINE_UPLOAD_* not set). Google Play will reject it.')
            }`;

module.exports = function withUploadSigning(config) {
  return withAppBuildGradle(config, (cfg) => {
    let gradle = cfg.modResults.contents;
    if (gradle.includes(MARKER)) return cfg;

    // 1. Add a release signing config after the debug one.
    const debugConfig = /(signingConfigs\s*\{\s*debug\s*\{[^}]*\})/;
    if (!debugConfig.test(gradle)) throw new Error('with-upload-signing: signingConfigs.debug not found in app/build.gradle');
    gradle = gradle.replace(debugConfig, `$1${RELEASE_SIGNING_CONFIG}`);

    // 2. Point the release build type at it.
    const releaseUsesDebug = /(buildTypes\s*\{[\s\S]*?release\s*\{[\s\S]*?)signingConfig signingConfigs\.debug/;
    if (!releaseUsesDebug.test(gradle)) throw new Error('with-upload-signing: release signingConfig not found in app/build.gradle');
    gradle = gradle.replace(releaseUsesDebug, `$1${RELEASE_SIGNING_LINE}`);

    cfg.modResults.contents = gradle;
    return cfg;
  });
};
